  FT["SG-H2103"] = {"id":"SG-H2103","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S667-2004?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Income Tax (Exemption of Foreign Income) Order 2004","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S667-2004","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2103-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Exemption of Foreign Income) Order 2004."}},{"id":"SG-H2103-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2. 3M Singapore Pte Ltd is hereby granted exemption from tax on the foreign dividends received in Singapore from any country outside Singapore, subject to the terms and conditions specified in the letter of approval dated 20th August 2004 addressed to 3M Company."}}],"pack":"sg-p27"};
  FT["SG-H2104"] = {"id":"SG-H2104","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S379-2005?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Income Tax (Exemption of Foreign Income) Order 2005","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S379-2005","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2104-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Exemption of Foreign Income) Order 2005."}},{"id":"SG-H2104-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2. Singapore Telecommunications Limited is hereby granted exemption from tax on the foreign dividends received in Singapore by the company from a country outside Singapore, arising from the company’s disposal of its interest in Belgacom S.A. in Belgium, subject to the condition specified in the letter of approval dated 30th March 2004 addressed to the company."}}],"pack":"sg-p27"};
  FT["SG-H2105"] = {"id":"SG-H2105","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S436-2006?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Income Tax (Exemption of Foreign Income) Order 2006","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S436-2006","completenessNote":"全文，共 7 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2105-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Exemption of Foreign Income) Order 2006."}},{"id":"SG-H2105-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption for Allco Investments No. 1 Pte Ltd and Allco Investments No. 2 Pte Ltd"},"text":{"en":"2. Allco Investments No. 1 Pte Ltd and Allco Investments No. 2 Pte Ltd shall, with effect from 2nd February 2006, be exempt from tax on any distribution derived outside Singapore from a foreign trust and received in Singapore, subject to the conditions specified in the letter of approval dated 2nd February 2006 addressed to their tax agent."}},{"id":"SG-H2105-A3","no":3,"noLabel":{"en":"3."},"heading":{"en":"Exemption for Javana Pte Ltd, Somerset Grand Citra (S) Pte Ltd, Ascott Residences Pte Ltd and Somerset Philippines (S) Pte Ltd"},"text":{"en":"3. Javana Pte Ltd, Somerset Grand Citra (S) Pte Ltd, Ascott Residences Pte Ltd and Somerset Philippines (S) Pte Ltd shall, with effect from 6th January 2006, be exempt from tax on any interest derived from outside Singapore and received in Singapore, subject to the conditions specified in the letter of approval dated 6th January 2006 addressed to their tax agent."}},{"id":"SG-H2105-A4","no":4,"noLabel":{"en":"4."},"heading":{"en":"Exemption for Hemliner Pte Ltd and Glenwood Properties Pte Ltd"},"text":{"en":"4. Hemliner Pte Ltd and Glenwood Properties Pte Ltd shall, with effect from 8th February 2006, be exempt from tax on any interest derived from outside Singapore and received in Singapore, subject to the conditions specified in the letter of approval dated 8th February 2006 addressed to their tax agent."}},{"id":"SG-H2105-A5","no":5,"noLabel":{"en":"5."},"heading":{"en":"Exemption for Mapletree Logistics Trust"},"text":{"en":"5. Mapletree Logistics Trust shall —\n(a)with effect from 8th December 2005, be exempt from tax on any dividend derived from outside Singapore (being paid out of rental income earned in China and Hong Kong) and received in Singapore, subject to the conditions specified in the letter of approval dated 8th December 2005 addressed to the tax agent of Mapletree Logistics Trust;\n(b)with effect from 6th January 2006, be exempt from tax on any interest derived from outside Singapore (being paid out of rental income earned in China) and received in Singapore, subject to the conditions specified in the letter of approval dated 6th January 2006 addressed to the tax agent of Mapletree Logistics Trust; and\n(c)with effect from 8th February 2006, be exempt from tax on any interest derived from outside Singapore (being paid out of rental income earned in Hong Kong) and received in Singapore, subject to the conditions specified in the letter of approval dated 8th February 2006 addressed to the tax agent of Mapletree Logistics Trust."}},{"id":"SG-H2105-A6","no":6,"noLabel":{"en":"6."},"heading":{"en":"Exemption for MapletreeLog Malaysia Holdings Pte Ltd"},"text":{"en":"6. MapletreeLog Malaysia Holdings Pte Ltd shall —\n(a)with effect from 8th December 2005, be exempt from tax on any dividend derived from outside Singapore (being paid out of rental income earned in Malaysia) and received in Singapore, subject to the conditions specified in the letter of approval dated 8th December 2005 addressed to its tax agent; and\n(b)with effect from 6th January 2006, be exempt from tax on any interest derived from outside Singapore (being paid out of rental income earned in Malaysia) and received in Singapore, subject to the conditions specified in the letters of approval dated 6th January 2006 addressed to its tax agent."}},{"id":"SG-H2105-A7","no":7,"noLabel":{"en":"7."},"heading":{"en":"Exemption for CapitaCommercial Trust"},"text":{"en":"7. CapitaCommercial Trust shall, with effect from 14th February 2006, be exempt from tax on any interest derived from outside Singapore and received in Singapore, subject to the conditions specified in the letter of approval dated 14th February 2006 addressed to the tax agent of CapitaCommercial Trust."}}],"pack":"sg-p27"};
  FT["SG-H2106"] = {"id":"SG-H2106","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S366-2007?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Income Tax (Exemption of Foreign Income) Order 2007","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S366-2007","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2106-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Exemption of Foreign Income) Order 2007."}},{"id":"SG-H2106-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2. United International Securities Ltd is hereby granted exemption from tax on the dividends received in Singapore from its subsidiaries in Korea (Daewoo Shipbuilding & Marine Engineering Co Ltd, KT&G Corporation) and Indonesia (P.T. Astra International Tbk, P.T. Telekomunikasi Indonesia Tbk), subject to the terms and conditions specified in the letter of approval dated 5th January 2007 addressed to the company."}}],"pack":"sg-p27"};
