  FT["SG-H2110"] = {"id":"SG-H2110","coverage":"full","language":"en","sourceName":"Attorney-General's Chambers, Singapore Statutes Online (SSO)","sourceUrl":"https://sso.agc.gov.sg/SL/ITA1947-S247-2011?ViewType=Print&PrintType=html&ProvIds=all-.","fetchedAt":"2026-10-07","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Income Tax (Exemption of Foreign Income) Order 2011","orig":null},"level":"regulation","status":"active","docNumber":"Subsidiary Legislation ITA1947-S247-2011","completenessNote":"全文，共 2 条；逐字取自新加坡法规在线（SSO）官方打印视图，未改写、未节选。","country":"SG","countryName":"新加坡","layer":"intl","articles":[{"id":"SG-H2110-A1","no":1,"noLabel":{"en":"1."},"heading":{"en":"Citation"},"text":{"en":"1. This Order may be cited as the Income Tax (Exemption of Foreign Income) Order 2011."}},{"id":"SG-H2110-A2","no":2,"noLabel":{"en":"2."},"heading":{"en":"Exemption"},"text":{"en":"2.—(1) CapitaRetail China Development Fund is hereby granted exemption from tax on the dividend income received in Singapore from CapitaRetail China Developments (B) Pte Ltd.\n(2) The exemption under sub-paragraph (1) —\n(a)is subject to the terms and conditions specified in the letter of approval dated 28th March 2011 addressed to the tax agent of CapitaRetail China Development Fund; and\n(b)applies to dividend income received on or after 10th January 2011."}}],"pack":"sg-p27"};
